// ====================================================
// UNIVERSAL AVATAR RENDERER
// ====================================================
window.ETHITH_RENDER_USER_AVATAR = function(user, size, extraClass, extraStyle) {
  var s = size || 36;
  var cls = extraClass || "";
  var st = extraStyle || "";
  var u = user || {};

  var avatarObj = null;
  if (u.avatar) {
    if (typeof u.avatar === "string") {
      avatarObj = (window.ETHITH_AVATARS || []).find(function(a) { return a.id === u.avatar; });
    } else if (u.avatar.id) {
      avatarObj = (window.ETHITH_AVATARS || []).find(function(a) { return a.id === u.avatar.id; }) || u.avatar;
    }
  }

  if (avatarObj && avatarObj.svg) {
    return '<div class="eth-avatar-circle ' + cls + '" style="width:' + s + 'px;height:' + s + 'px;border-radius:50%;overflow:hidden;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,0.18);display:inline-flex;align-items:center;justify-content:center;background:' + (avatarObj.bg || '#1e293b') + ';border:2px solid ' + (avatarObj.border || 'rgba(255,255,255,0.25)') + ';' + st + '" title="' + (avatarObj.name || '') + '">' +
      avatarObj.svg +
    '</div>';
  }

  // Fallback: Initial letter
  var initial = (u.name && u.name.trim()) ? u.name.trim().charAt(0).toUpperCase() : "U";
  return '<div class="eth-avatar-circle eth-avatar-fallback ' + cls + '" style="width:' + s + 'px;height:' + s + 'px;border-radius:50%;background:linear-gradient(135deg, #2563eb, #1d4ed8);color:#ffffff;font-weight:800;font-size:' + Math.round(s * 0.45) + 'px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;border:2px solid rgba(255,255,255,0.2);box-shadow:0 2px 6px rgba(0,0,0,0.15);' + st + '">' +
    initial +
  '</div>';
};

// ====================================================
// PACK OPENING DROP LOGIC (RNG & 15-PACK PITY SYSTEM)
// ====================================================
window.ETHITH_OPEN_PACK = function(packId, user) {
  var pack = (window.ETHITH_PACKS || []).find(function(p) { return p.id === packId; });
  if (!pack) return null;

  if (!user) user = (window.EthithApp && window.EthithApp.state && window.EthithApp.state.user) || {};
  var userKey = (user.email || user.name || 'guest').toLowerCase().trim().replace(/\s+/g, '_');
  var pityStorageKey = 'ethith_pack_daily_pity_' + userKey;
  var dateStorageKey = 'ethith_pack_daily_date_' + userKey;

  // Daily calendar date check (Midnight 00:00 reset)
  var todayDateStr = (function() {
    var d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  })();

  var userPityDate = user.dailyPityDate || localStorage.getItem(dateStorageKey) || '';
  if (userPityDate !== todayDateStr) {
    user.dailyPityCount = 0;
    user.dailyPityDate = todayDateStr;
    try {
      localStorage.setItem(pityStorageKey, '0');
      localStorage.setItem(dateStorageKey, todayDateStr);
    } catch(e) {}
  }

  var currentDailyPity = 0;
  try {
    currentDailyPity = Number(user.dailyPityCount !== undefined ? user.dailyPityCount : (localStorage.getItem(pityStorageKey) || 0));
  } catch(e) {}

  // 10-PACK DAILY PITY RULE:
  // If user opens 10 packs in a day (currentDailyPity >= 9, making this the 10th pack): 100% Epic or Legendary (50/50)!
  var isDailyPityTriggered = (currentDailyPity >= 9);
  var rarity = "Common";

  if (isDailyPityTriggered) {
    // 100% GUARANTEED EPIC OR LEGENDARY
    rarity = (Math.random() < 0.5) ? "Legendary" : "Epic";
    currentDailyPity = 0; // Reset to 0 after guarantee trigger
  } else {
    // Normal RNG
    var rand = Math.random() * 100;
    if (rand < 7) rarity = "Legendary";
    else if (rand < 25) rarity = "Epic";
    else if (rand < 55) rarity = "Rare";
    else rarity = "Common";

    // CRITICAL USER RULE:
    // "agar u to'lmasdan o'quvchiga legent yoki epic narsa tushsa aftamatik boyagi garantiya 0 ga tenglashadi"
    if (rarity === "Epic" || rarity === "Legendary") {
      currentDailyPity = 0; // Reset to 0 if epic or legendary drops early
    } else {
      currentDailyPity += 1; // Increment towards 10
    }
  }

  user.dailyPityCount = currentDailyPity;
  user.dailyPityDate = todayDateStr;
  try {
    localStorage.setItem(pityStorageKey, String(currentDailyPity));
    localStorage.setItem(dateStorageKey, todayDateStr);
  } catch(e) {}

  // ==========================================
  // DROP LOGIC BY PACK TYPE
  // ==========================================
  
  // Helper to get random avatar matching query
  function getDropAvatar(gender, filterFn) {
    var pool = (window.ETHITH_AVATARS || []).filter(function(a) {
      if (gender && a.gender !== gender) return false;
      if (filterFn && !filterFn(a)) return false;
      return a.rarity === rarity || !rarity;
    });
    if (!pool.length) {
      pool = (window.ETHITH_AVATARS || []).filter(function(a) {
        if (gender && a.gender !== gender) return false;
        return a.rarity === rarity || !rarity;
      });
    }
    if (!pool.length) pool = (window.ETHITH_AVATARS || []);
    return pool[Math.floor(Math.random() * pool.length)];
  }

  // 1. DAILY FREE PACK
  if (pack.type === "daily") {
    var roll = Math.random() * 100;
    if (roll < 60) {
      var coinAmounts = (rarity === "Legendary") ? [1200, 1600, 2200] : ((rarity === "Epic") ? [500, 650, 850] : ((rarity === "Rare") ? [240, 320, 420] : [100, 160, 200]));
      var amount = coinAmounts[Math.floor(Math.random() * coinAmounts.length)];
      return { type: "coins", rarity: rarity, amount: amount, name: amount + " ETHITH Coin!", desc: "Kunlik qutidan tushgan xazina! Hamyoningizga darhol qo'shildi!", icon: "🪙" };
    } else if (roll < 85) {
      var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
      return { type: "prize", rarity: (pz ? pz.rarity : rarity), item: pz, name: pz ? pz.name : "Kutilmagan Sovg'a", desc: pz ? pz.desc : "Kunlik sovrin!", icon: pz ? pz.icon : "🎁" };
    } else {
      var unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault && (e.rarity === rarity || !rarity); });
      if (!unlEmojis.length) unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
      var em = unlEmojis[Math.floor(Math.random() * unlEmojis.length)];
      return { type: "emoji", rarity: em.rarity, emoji: em.emoji, name: em.emoji + " " + em.name, desc: "Telegram chat va reaksiyalar uchun ochildi!", icon: em.emoji };
    }
  }

  // 2. PRIZE PACK
  if (pack.type === "prize") {
    var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
    return { type: "prize", rarity: (pz ? pz.rarity : rarity), item: pz, name: pz ? pz.name : "Omadli Sovg'a", desc: pz ? pz.desc : "Ajoyib sovrin!", icon: pz ? pz.icon : "💎", coinPrice: pz ? pz.price : (rarity === "Legendary" ? 1000 : (rarity === "Epic" ? 450 : (rarity === "Rare" ? 200 : 80))) };
  }

  // 3. EMOJI PACK
  if (pack.type === "emoji") {
    var matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault && (e.rarity === rarity || !rarity); });
    if (!matching.length) matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
    var chosen = matching[Math.floor(Math.random() * matching.length)];
    return { type: "emoji", rarity: chosen.rarity, emoji: chosen.emoji, name: chosen.emoji + " " + chosen.name, desc: "Telegram chat va barcha reaksiyalarda endi erkin foydalanishingiz mumkin!", icon: chosen.emoji };
  }

  // 4. BOYS AVATAR PACK
  if (pack.type === "avatar_boy") {
    var boy = getDropAvatar("boy");
    return { type: "avatar", rarity: boy.rarity, avatar: boy, name: boy.name, desc: boy.tagline, icon: boy.name };
  }

  // 5. GIRLS AVATAR PACK
  if (pack.type === "avatar_girl") {
    var girl = getDropAvatar("girl");
    return { type: "avatar", rarity: girl.rarity, avatar: girl, name: girl.name, desc: girl.tagline, icon: girl.name };
  }

  // 6. UNIVERSAL MEGA PACK
  if (pack.type === "mega") {
    var catRoll = Math.random() * 100;
    if (catRoll < 25) {
      var coinAmounts = (rarity === "Legendary") ? [1250, 1650, 2500] : ((rarity === "Epic") ? [600, 750, 950] : ((rarity === "Rare") ? [300, 420, 500] : [180, 220, 260]));
      var amount = coinAmounts[Math.floor(Math.random() * coinAmounts.length)];
      return { type: "coins", rarity: rarity, amount: amount, name: amount + " ETHITH Coin!", desc: "Universal Mega Packdan xazina!", icon: "🪙" };
    } else if (catRoll < 50) {
      var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
      return { type: "prize", rarity: (pz ? pz.rarity : rarity), item: pz, name: pz ? pz.name : "Omadli Sovg'a", desc: pz ? pz.desc : "Mega Packdan tushgan maxsus sovrin!", icon: pz ? pz.icon : "💎", coinPrice: pz ? pz.price : (rarity === "Legendary" ? 1000 : (rarity === "Epic" ? 450 : 200)) };
    } else if (catRoll < 70) {
      var matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault && (e.rarity === rarity || !rarity); });
      if (!matching.length) matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
      var chosenEm = matching[Math.floor(Math.random() * matching.length)];
      return { type: "emoji", rarity: chosenEm.rarity, emoji: chosenEm.emoji, name: chosenEm.emoji + " " + chosenEm.name, desc: "Universal Mega Packdan chat emojisi ochildi!", icon: chosenEm.emoji };
    } else if (catRoll < 85) {
      var boy = getDropAvatar("boy");
      return { type: "avatar", rarity: boy.rarity, avatar: boy, name: boy.name, desc: boy.tagline, icon: boy.name };
    } else {
      var girl = getDropAvatar("girl");
      return { type: "avatar", rarity: girl.rarity, avatar: girl, name: girl.name, desc: girl.tagline, icon: girl.name };
    }
  }

  // 7-20: THEMED PACKS (Cyber, Dragon, Galaxy, Crown, Ninja, Pharaoh, Wizard, Steampunk, Atlantis, Blackhole, Samurai, Cyberpunk2099, Phoenix, Gods)
  var themeAvFilter = function(a) {
    var id = (a.id + ' ' + (a.name || '')).toLowerCase();
    if (pack.type === 'cyber_neon') return id.includes('cyber') || id.includes('neon') || id.includes('mecha') || id.includes('matrix');
    if (pack.type === 'mythic_dragon') return id.includes('dragon') || id.includes('phoenix') || id.includes('flame');
    if (pack.type === 'galaxy_nebula') return id.includes('galaxy') || id.includes('cosmic') || id.includes('star') || id.includes('space');
    if (pack.type === 'royal_crown') return id.includes('emperor') || id.includes('king') || id.includes('queen') || id.includes('crown') || id.includes('royal');
    if (pack.type === 'shadow_ninja') return id.includes('ninja') || id.includes('shinobi') || id.includes('ghost') || id.includes('shadow');
    if (pack.type === 'ancient_pharaoh') return id.includes('pharaoh') || id.includes('cleopatra') || id.includes('relic') || id.includes('ancient');
    if (pack.type === 'magic_wizard') return id.includes('wizard') || id.includes('merlin') || id.includes('sorceress') || id.includes('magic');
    if (pack.type === 'steampunk_clock') return id.includes('steam') || id.includes('chrono') || id.includes('gear') || id.includes('pilot');
    if (pack.type === 'atlantis_ocean') return id.includes('triton') || id.includes('mermaid') || id.includes('ocean') || id.includes('atlantis');
    if (pack.type === 'cosmic_blackhole') return id.includes('blackhole') || id.includes('quantum') || id.includes('void') || id.includes('singularity');
    if (pack.type === 'samurai_honor') return id.includes('samurai') || id.includes('kage') || id.includes('katana') || id.includes('bushido');
    if (pack.type === 'cyberpunk_2099') return id.includes('cyber') || id.includes('matrix') || id.includes('hacker') || id.includes('sniper');
    if (pack.type === 'phoenix_fire') return id.includes('phoenix') || id.includes('flame') || id.includes('blaze') || id.includes('fire');
    if (pack.type === 'immortal_gods') return id.includes('god') || id.includes('zeus') || id.includes('athena') || id.includes('olympus');
    return true;
  };

  var roll = Math.random() * 100;
  if (roll < 45) {
    // 45% chance Themed Avatar
    var av = getDropAvatar(null, themeAvFilter);
    return {
      type: "avatar",
      rarity: av.rarity,
      avatar: av,
      name: av.name,
      desc: pack.name + "dan afsonaviy personaj ochildi!",
      icon: av.name
    };
  } else if (roll < 75) {
    // 30% chance Large Coins
    var amounts = (rarity === "Legendary") ? [1000, 1500, 2000] : ((rarity === "Epic") ? [600, 800, 1100] : ((rarity === "Rare") ? [350, 500, 700] : [200, 300, 400]));
    var amt = amounts[Math.floor(Math.random() * amounts.length)];
    return {
      type: "coins",
      rarity: rarity,
      amount: amt,
      name: amt + " ETHITH Coin!",
      desc: pack.name + " maxsus xazinasidan chiqqan tangalar!",
      icon: pack.icon || "🪙"
    };
  } else {
    // 25% chance Themed Emoji or Prize
    var unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault && (e.rarity === rarity || !rarity); });
    if (!unlEmojis.length) unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
    var em = unlEmojis[Math.floor(Math.random() * unlEmojis.length)];
    return {
      type: "emoji",
      rarity: em.rarity,
      emoji: em.emoji,
      name: em.emoji + " " + em.name,
      desc: pack.name + " maxsus emojisi ochildi!",
      icon: em.emoji
    };
  }
};

